BASH_FUNC_head%%:
() {  local _a;
 for _a in "$@";
 do
 [ "$_a" != "-n" ] && [ "${_a#-}" = "$_a" ] && [ -f "$_a" ] && { 
 _2s_urgent "file truncation (head $_a)" "ffs read $_a — reads the FULL file (1M context); no reason to truncate";
 command ffs read "$_a" 2> /dev/null || command head "$@";
 return $?
 };
 done;
 if [ -p /dev/stdin ]; then
 _2s_urgent "pipeline truncation (head) — persist FULL output" "run the upstream fully; read the file/result via ffs — never pipe head";
 return 126;
 fi;
 command head "$@"
}

BASH_FUNC__2s_urgent%%:
() {  echo "════ [kairos GUARD — URGENT, CANCELLED] ════";
 echo "  $1";
 echo "  MUST DO: $2"
}

BASH_FUNC__2s_wrap%%:
() {  local b="$1";
 shift;
 local probe;
 probe="$b $*";
 _2s_guard "$probe" || return 126;
 if _2s_slow "$b" "$1"; then
 "$RF_BIN" "$b" "$@";
 else
 command "$b" "$@";
 fi
}

BASH_FUNC__2s_guard%%:
() {  local _c="${1:-$BASH_COMMAND}";
 case "$_c" in 
 _2s_* | *two-sec* | *print_doctrine_hint*)
 return 0
 ;;
 *">/dev/null"* | *"> /dev/null"* | *"2>/dev/null"* | *"2> /dev/null"* | *"1>/dev/null"* | *"1> /dev/null"* | *"&>/dev/null"*)
 _2s_urgent "output discarded to /dev/null" "drop the redirect — full output or bust";
 return 1
 ;;
 *"| true"* | *"|true"* | *"|  true"*)
 _2s_urgent "'| true' swallows the exit code" "handle the failure explicitly";
 return 1
 ;;
 *"2>&1"*)
 _2s_urgent "'2>&1' merges stderr into stdout" "keep streams separate — no &2 merges";
 return 1
 ;;
 *"| head"* | *"|head"* | *"| tail"* | *"|tail"* | *"| wc -l"* | *"|wc -l"*)
 _2s_urgent "pipeline truncation (head/tail/wc)" "persist FULL output; read via ffs";
 return 1
 ;;
 *[[:space:]]sleep[[:space:]][0-9]*)
 _2s_urgent "blocking sleep" "readiness-check or background it — never sleep to wait";
 return 1
 ;;
 *[[:space:]]head[[:space:]]-[[:space:]]*c* | *[[:space:]]tail[[:space:]]-[[:space:]]*c*)
 _2s_urgent "byte truncation (head/tail -c)" "persist full output; slice in code only";
 return 1
 ;;
 esac;
 return 0
}

BASH_FUNC_tail%%:
() {  [ "$1" = "-f" ] && { 
 command tail "$@";
 return $?
 };
 local _a;
 for _a in "$@";
 do
 [ "$_a" != "-n" ] && [ "${_a#-}" = "$_a" ] && [ -f "$_a" ] && { 
 _2s_urgent "file truncation (tail $_a)" "ffs read $_a --full — full tail is the end of a full read";
 command ffs read "$_a" --full 2> /dev/null || command tail "$@";
 return $?
 };
 done;
 if [ -p /dev/stdin ]; then
 _2s_urgent "pipeline truncation (tail) — persist FULL output" "run the upstream fully; read the result via ffs — never pipe tail";
 return 126;
 fi;
 command tail "$@"
}

