BASH_FUNC_two_sec_slow%%:
() {  case "$1:$2" in 
 git:push | git:pull | git:fetch | git:clone | git:merge | git:rebase | git:submodule | git:gc | git:filter-repo)
 return 0
 ;;
 bun:install | bun:add | bun:remove | bun:update | bun:test | bun:build | bun:publish | bun:link | bun:run)
 return 0
 ;;
 npm:install | npm:ci | npm:update | npm:build | npm:test | npm:publish)
 return 0
 ;;
 pnpm:add | pnpm:install | pnpm:update)
 return 0
 ;;
 pip:install | pip3:install | uv:sync | uv:add | uv:lock)
 return 0
 ;;
 gh:repo | gh:pr | gh:release | gh:api | gh:create | gh:auth | gh:secret | gh:run | gh:issue | gh:search)
 return 0
 ;;
 gitleaks:git | gitleaks:detect)
 return 0
 ;;
 codebase-memory:*)
 return 0
 ;;
 cargo:build | cargo:test | cargo:check | go:build | go:test | go:vet | make:*)
 return 0
 ;;
 ffs:index | ffs:map)
 return 0
 ;;
 *)
 return 1
 ;;
 esac
}

